-- ERPNext breadth: production execution, asset lifecycle, project costing,
-- support SLA, expense claims, POS sessions and regional integration seams.

CREATE TABLE IF NOT EXISTS asset_lifecycle_entries (
  tenant_id TEXT NOT NULL,
  voucher_type TEXT NOT NULL,
  voucher_no TEXT NOT NULL,
  voucher_revision INTEGER NOT NULL,
  line_key TEXT NOT NULL,
  asset TEXT NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN ('Movement','Maintenance','Disposal')),
  posting_at TEXT NOT NULL,
  location TEXT,
  custodian TEXT,
  amount_minor INTEGER NOT NULL DEFAULT 0,
  currency TEXT,
  currency_scale INTEGER CHECK(currency_scale BETWEEN 0 AND 6),
  PRIMARY KEY(tenant_id,voucher_type,voucher_no,voucher_revision,line_key)
);
CREATE INDEX IF NOT EXISTS idx_asset_lifecycle_asset
  ON asset_lifecycle_entries(tenant_id,asset,kind,posting_at);

CREATE TRIGGER IF NOT EXISTS asset_single_disposal_guard
BEFORE INSERT ON asset_lifecycle_entries
WHEN NEW.kind='Disposal'
BEGIN
  SELECT CASE WHEN
    COALESCE((SELECT SUM(CASE WHEN line_key LIKE 'REV-%' THEN -1 ELSE 1 END)
      FROM asset_lifecycle_entries WHERE tenant_id=NEW.tenant_id AND asset=NEW.asset AND kind='Disposal'),0)
      + CASE WHEN NEW.line_key LIKE 'REV-%' THEN -1 ELSE 1 END NOT IN (0,1)
    THEN RAISE(ABORT,'ASSET_DISPOSAL_STATE_INVALID') END;
END;

CREATE TABLE IF NOT EXISTS project_time_entries (
  tenant_id TEXT NOT NULL,
  voucher_type TEXT NOT NULL,
  voucher_no TEXT NOT NULL,
  voucher_revision INTEGER NOT NULL,
  line_key TEXT NOT NULL,
  project TEXT NOT NULL,
  task TEXT,
  hours_micros INTEGER NOT NULL,
  cost_minor INTEGER NOT NULL,
  billing_minor INTEGER NOT NULL,
  currency TEXT NOT NULL,
  currency_scale INTEGER NOT NULL CHECK(currency_scale BETWEEN 0 AND 6),
  posting_at TEXT NOT NULL,
  PRIMARY KEY(tenant_id,voucher_type,voucher_no,voucher_revision,line_key)
);
CREATE INDEX IF NOT EXISTS idx_project_time_project
  ON project_time_entries(tenant_id,project,task,posting_at);

CREATE TRIGGER IF NOT EXISTS project_time_nonnegative_guard
BEFORE INSERT ON project_time_entries
BEGIN
  SELECT CASE WHEN
    COALESCE((SELECT SUM(hours_micros) FROM project_time_entries
      WHERE tenant_id=NEW.tenant_id AND project=NEW.project AND COALESCE(task,'')=COALESCE(NEW.task,'')),0)
      + NEW.hours_micros < 0
    THEN RAISE(ABORT,'PROJECT_TIME_NEGATIVE') END;
END;

CREATE TABLE IF NOT EXISTS pos_sales_entries (
  tenant_id TEXT NOT NULL,
  voucher_type TEXT NOT NULL,
  voucher_no TEXT NOT NULL,
  voucher_revision INTEGER NOT NULL,
  line_key TEXT NOT NULL,
  pos_profile TEXT NOT NULL,
  opening_entry TEXT NOT NULL,
  invoice TEXT NOT NULL,
  net_total_minor INTEGER NOT NULL,
  tax_total_minor INTEGER NOT NULL,
  grand_total_minor INTEGER NOT NULL,
  currency TEXT NOT NULL,
  currency_scale INTEGER NOT NULL CHECK(currency_scale BETWEEN 0 AND 6),
  posting_at TEXT NOT NULL,
  PRIMARY KEY(tenant_id,voucher_type,voucher_no,voucher_revision,line_key)
);
CREATE INDEX IF NOT EXISTS idx_pos_sales_session
  ON pos_sales_entries(tenant_id,opening_entry,posting_at);

CREATE TRIGGER IF NOT EXISTS pos_closing_unique_insert
BEFORE INSERT ON documents
WHEN NEW.doctype='POS Closing Entry' AND NEW.docstatus=1
  AND EXISTS(SELECT 1 FROM documents d WHERE d.tenant_id=NEW.tenant_id AND d.doctype='POS Closing Entry'
    AND d.docstatus=1 AND json_extract(d.payload_json,'$.opening_entry')=json_extract(NEW.payload_json,'$.opening_entry'))
BEGIN SELECT RAISE(ABORT,'POS_SESSION_ALREADY_CLOSED'); END;

CREATE TRIGGER IF NOT EXISTS pos_closing_unique_update
BEFORE UPDATE OF docstatus,payload_json ON documents
WHEN NEW.doctype='POS Closing Entry' AND NEW.docstatus=1
  AND EXISTS(SELECT 1 FROM documents d WHERE d.tenant_id=NEW.tenant_id AND d.doctype='POS Closing Entry'
    AND d.docstatus=1 AND d.doc_key<>NEW.doc_key
    AND json_extract(d.payload_json,'$.opening_entry')=json_extract(NEW.payload_json,'$.opening_entry'))
BEGIN SELECT RAISE(ABORT,'POS_SESSION_ALREADY_CLOSED'); END;

CREATE TRIGGER IF NOT EXISTS pos_invoice_closed_session_insert
BEFORE INSERT ON documents
WHEN NEW.doctype='POS Invoice' AND NEW.docstatus=1
  AND EXISTS(SELECT 1 FROM documents d WHERE d.tenant_id=NEW.tenant_id AND d.doctype='POS Closing Entry'
    AND d.docstatus=1 AND json_extract(d.payload_json,'$.opening_entry')=json_extract(NEW.payload_json,'$.opening_entry'))
BEGIN SELECT RAISE(ABORT,'POS_SESSION_CLOSED'); END;

CREATE TRIGGER IF NOT EXISTS pos_invoice_closed_session_update
BEFORE UPDATE OF docstatus,payload_json ON documents
WHEN NEW.doctype='POS Invoice' AND NEW.docstatus=1
  AND EXISTS(SELECT 1 FROM documents d WHERE d.tenant_id=NEW.tenant_id AND d.doctype='POS Closing Entry'
    AND d.docstatus=1 AND json_extract(d.payload_json,'$.opening_entry')=json_extract(NEW.payload_json,'$.opening_entry'))
BEGIN SELECT RAISE(ABORT,'POS_SESSION_CLOSED'); END;

CREATE TRIGGER IF NOT EXISTS job_card_completion_guard_insert
BEFORE INSERT ON documents
WHEN NEW.doctype='Job Card' AND NEW.docstatus=1
BEGIN
  SELECT CASE WHEN
    COALESCE((SELECT SUM(CAST(json_extract(j.payload_json,'$.completed_qty_micros') AS INTEGER)) FROM documents j
      WHERE j.tenant_id=NEW.tenant_id AND j.doctype='Job Card' AND j.docstatus=1
        AND json_extract(j.payload_json,'$.work_order')=json_extract(NEW.payload_json,'$.work_order')),0)
      + CAST(json_extract(NEW.payload_json,'$.completed_qty_micros') AS INTEGER)
      > COALESCE((SELECT CAST(json_extract(w.payload_json,'$.qty_micros') AS INTEGER) FROM documents w
        WHERE w.tenant_id=NEW.tenant_id AND w.doctype='Work Order' AND w.name=json_extract(NEW.payload_json,'$.work_order') AND w.docstatus=1),-1)
    THEN RAISE(ABORT,'JOB_CARD_OVER_COMPLETION') END;
END;

CREATE TRIGGER IF NOT EXISTS job_card_completion_guard_update
BEFORE UPDATE OF docstatus,payload_json ON documents
WHEN NEW.doctype='Job Card' AND NEW.docstatus=1
BEGIN
  SELECT CASE WHEN
    COALESCE((SELECT SUM(CAST(json_extract(j.payload_json,'$.completed_qty_micros') AS INTEGER)) FROM documents j
      WHERE j.tenant_id=NEW.tenant_id AND j.doctype='Job Card' AND j.docstatus=1 AND j.doc_key<>NEW.doc_key
        AND json_extract(j.payload_json,'$.work_order')=json_extract(NEW.payload_json,'$.work_order')),0)
      + CAST(json_extract(NEW.payload_json,'$.completed_qty_micros') AS INTEGER)
      > COALESCE((SELECT CAST(json_extract(w.payload_json,'$.qty_micros') AS INTEGER) FROM documents w
        WHERE w.tenant_id=NEW.tenant_id AND w.doctype='Work Order' AND w.name=json_extract(NEW.payload_json,'$.work_order') AND w.docstatus=1),-1)
    THEN RAISE(ABORT,'JOB_CARD_OVER_COMPLETION') END;
END;

CREATE TRIGGER IF NOT EXISTS pos_open_session_unique_insert
BEFORE INSERT ON documents
WHEN NEW.doctype='POS Opening Entry' AND NEW.docstatus=1
  AND EXISTS(SELECT 1 FROM documents o WHERE o.tenant_id=NEW.tenant_id AND o.doctype='POS Opening Entry' AND o.docstatus=1
    AND json_extract(o.payload_json,'$.pos_profile')=json_extract(NEW.payload_json,'$.pos_profile')
    AND NOT EXISTS(SELECT 1 FROM documents c WHERE c.tenant_id=o.tenant_id AND c.doctype='POS Closing Entry' AND c.docstatus=1
      AND json_extract(c.payload_json,'$.opening_entry')=o.name))
BEGIN SELECT RAISE(ABORT,'POS_PROFILE_ALREADY_OPEN'); END;

CREATE TRIGGER IF NOT EXISTS pos_open_session_unique_update
BEFORE UPDATE OF docstatus,payload_json ON documents
WHEN NEW.doctype='POS Opening Entry' AND NEW.docstatus=1
  AND EXISTS(SELECT 1 FROM documents o WHERE o.tenant_id=NEW.tenant_id AND o.doctype='POS Opening Entry' AND o.docstatus=1
    AND o.doc_key<>NEW.doc_key AND json_extract(o.payload_json,'$.pos_profile')=json_extract(NEW.payload_json,'$.pos_profile')
    AND NOT EXISTS(SELECT 1 FROM documents c WHERE c.tenant_id=o.tenant_id AND c.doctype='POS Closing Entry' AND c.docstatus=1
      AND json_extract(c.payload_json,'$.opening_entry')=o.name))
BEGIN SELECT RAISE(ABORT,'POS_PROFILE_ALREADY_OPEN'); END;

CREATE VIEW IF NOT EXISTS asset_lifecycle_report AS
SELECT tenant_id,posting_at,voucher_type,voucher_no,asset,kind,location,custodian,
       amount_minor/100.0 AS amount,currency
FROM asset_lifecycle_entries;

CREATE VIEW IF NOT EXISTS project_profitability AS
SELECT tenant_id,project,currency,
       SUM(hours_micros)/1000000.0 AS actual_hours,
       SUM(cost_minor)/100.0 AS actual_cost,
       SUM(billing_minor)/100.0 AS billable_amount,
       (SUM(billing_minor)-SUM(cost_minor))/100.0 AS gross_margin
FROM project_time_entries GROUP BY tenant_id,project,currency;

CREATE VIEW IF NOT EXISTS pos_session_summary AS
SELECT tenant_id,opening_entry,pos_profile,currency,
       SUM(net_total_minor)/100.0 AS net_total,
       SUM(tax_total_minor)/100.0 AS tax_total,
       SUM(grand_total_minor)/100.0 AS grand_total,
       COUNT(DISTINCT invoice) AS invoice_count
FROM pos_sales_entries GROUP BY tenant_id,opening_entry,pos_profile,currency;

CREATE VIEW IF NOT EXISTS profit_and_loss AS
SELECT g.tenant_id,g.account,
       json_extract(m.data_json,'$.root_type') AS root_type,
       g.currency,SUM(g.debit_minor)/100.0 AS debit,SUM(g.credit_minor)/100.0 AS credit,
       CASE WHEN json_extract(m.data_json,'$.root_type')='Income'
            THEN (SUM(g.credit_minor)-SUM(g.debit_minor))/100.0
            ELSE (SUM(g.debit_minor)-SUM(g.credit_minor))/100.0 END AS balance
FROM gl_entries g JOIN master_records m ON m.tenant_id=g.tenant_id AND m.record_type='Account' AND m.name=g.account
WHERE json_extract(m.data_json,'$.root_type') IN ('Income','Expense')
GROUP BY g.tenant_id,g.account,root_type,g.currency;

CREATE VIEW IF NOT EXISTS balance_sheet AS
SELECT g.tenant_id,g.account,
       json_extract(m.data_json,'$.root_type') AS root_type,
       g.currency,SUM(g.debit_minor)/100.0 AS debit,SUM(g.credit_minor)/100.0 AS credit,
       CASE WHEN json_extract(m.data_json,'$.root_type')='Asset'
            THEN (SUM(g.debit_minor)-SUM(g.credit_minor))/100.0
            ELSE (SUM(g.credit_minor)-SUM(g.debit_minor))/100.0 END AS balance
FROM gl_entries g JOIN master_records m ON m.tenant_id=g.tenant_id AND m.record_type='Account' AND m.name=g.account
WHERE json_extract(m.data_json,'$.root_type') IN ('Asset','Liability','Equity')
GROUP BY g.tenant_id,g.account,root_type,g.currency;

CREATE VIEW IF NOT EXISTS cash_flow AS
SELECT g.tenant_id,g.account,g.currency,
       SUM(g.debit_minor-g.credit_minor)/100.0 AS net_cash_flow
FROM gl_entries g JOIN master_records m ON m.tenant_id=g.tenant_id AND m.record_type='Account' AND m.name=g.account
WHERE json_extract(m.data_json,'$.account_type') IN ('Cash','Bank')
GROUP BY g.tenant_id,g.account,g.currency;


